  'Co-admins can edit others’ meals': 'সহ-অ্যাডমিন অন্যদের মিল বদলাতে পারেন',
  'An admin always can. This decides whether a co-admin may too.': 'অ্যাডমিন সবসময়ই পারেন। সহ-অ্যাডমিনও পারবেন কি না, এটি সেটা ঠিক করে।',
  'Guest plates per sitting': 'প্রতি বেলায় অতিথির প্লেট',
  'The accounting policy': 'হিসাবের নীতি',
  'Put every expense into the meal rate': 'সব খরচ মিল রেটে ধরুন',
  'Off — the recommendation — keeps rent, wifi and electricity out of the rate, so somebody who eats out all month is not charged for meals they did not take.': 'বন্ধ রাখলে — যা আমরা পরামর্শ দিই — বাসা ভাড়া, ওয়াইফাই আর বিদ্যুৎ রেটের বাইরে থাকে, ফলে সারা মাস বাইরে খাওয়া কাউকে না খাওয়া মিলের টাকা দিতে হয় না।',
  'Rounding': 'রাউন্ডিং',
  'How the meal rate is rounded before anybody is billed with it.': 'কারো বিল করার আগে মিল রেট কীভাবে রাউন্ড করা হয়।',
  'Exact': 'হুবহু',
  'Nearest paisa': 'নিকটতম পয়সা',
  'Round up': 'উপরে রাউন্ড',
  'Whole taka': 'পুরো টাকা',
  'Anything but exact leaves a little over or under, which the settlement shows openly.': 'হুবহু ছাড়া অন্য যেকোনোটিতে সামান্য কম-বেশি থেকে যায়, যা হিসাব নিষ্পত্তিতে খোলাখুলি দেখানো হয়।',
  'Carry balances into next month': 'ব্যালেন্স পরের মাসে নিয়ে যান',
  'Off means every month starts clean and the mess settles in cash.': 'বন্ধ থাকলে প্রতিটি মাস শূন্য থেকে শুরু হয় আর মেস নগদে হিসাব মেটায়।',
  'Members can see the whole mess’s reports': 'সদস্যরা পুরো মেসের রিপোর্ট দেখতে পারেন',
  'Off narrows a member to their own figures. They always see the rate.': 'বন্ধ থাকলে সদস্য শুধু নিজের সংখ্যাগুলো দেখেন। রেট তাঁরা সবসময়ই দেখেন।',
  'Month starts on day': 'মাস শুরু হয় যে তারিখে',
  'Timezone': 'টাইমজোন',
  'Expense categories': 'খরচের খাত',
  'A category marked green counts toward the meal rate. The rest split their own way.': 'সবুজ চিহ্নিত খাত মিল রেটে গণনা করা হয়। বাকিগুলো নিজের নিয়মে ভাগ হয়।',
  'counts toward the meal rate': 'মিল রেটে গণনা হয়',
  'splits by: {mode}': 'ভাগ হয়: {mode}',
  'Which approvals this mess enforces': 'এই মেসে কোন কোন অনুমোদন লাগে',
  'Bazar needs approval': 'বাজারে অনুমোদন লাগে',
  'Off means a recorded bazar goes straight into the meal rate.': 'বন্ধ থাকলে রেকর্ড করা বাজার সরাসরি মিল রেটে চলে যায়।',
  'Expenses need approval': 'খরচে অনুমোদন লাগে',
  'Deposits need approval': 'জমায় অনুমোদন লাগে',
  'New members need approval': 'নতুন সদস্যে অনুমোদন লাগে',
  'Off means anybody with the code joins immediately.': 'বন্ধ থাকলে কোড থাকলেই যে কেউ সাথে সাথে যোগ দিতে পারেন।',
  'Turning an approval off does not change the arithmetic — only approved records ever count, and without the step they are approved as they are written.': 'অনুমোদন বন্ধ করলে হিসাব বদলায় না — শুধু অনুমোদিত রেকর্ডই গণনায় ধরা হয়, আর এই ধাপ না থাকলে লেখার সাথে সাথেই সেগুলো অনুমোদিত হয়ে যায়।',
  'Archive this mess': 'এই মেস আর্কাইভ করুন',
