  'Breakfast usually locks the night before — by morning the eggs are already bought.': 'সকালের খাবার সাধারণত আগের রাতেই লক হয় — সকাল হতে হতে ডিম তো কেনা হয়েই যায়।',
  'Counts toward the meal rate': 'মিল রেটে গণনা হয়',
  'No': 'না',
  'In use': 'চালু আছে',
  'Turned off': 'বন্ধ',
  'Turning a sitting off keeps every past meal readable — it just leaves tomorrow’s form.': 'কোনো বেলা বন্ধ করলেও আগের সব মিল দেখা যায় — শুধু আগামীকালের ফর্ম থেকে সেটি সরে যায়।',
  'Does this count toward the meal rate?': 'এটি কি মিল রেটে গণনা হবে?',
  'Yes — it is food': 'হ্যাঁ — এটি খাবার',
