  'It will be split the way you choose below, whatever anybody ate.': 'কে কী খেয়েছেন তা না দেখে, নিচে আপনি যেভাবে বাছবেন সেভাবে এটি ভাগ হবে।',
  'How it usually splits': 'সাধারণত যেভাবে ভাগ হয়',
