  'A rate needs two things: meals eaten, and money spent on food. Neither has been recorded this month yet.': 'রেট বের করতে দুটি জিনিস লাগে: খাওয়া মিল, আর খাবারে খরচ করা টাকা। এই মাসে এখনো কোনোটিই রেকর্ড হয়নি।',
  '{n} meals recorded, but no food cost yet. Add a bazar or an expense and the rate appears.': '{n}টি মিল রেকর্ড হয়েছে, কিন্তু খাবারের খরচ এখনো নেই। একটি বাজার বা খরচ যোগ করলেই রেট দেখা যাবে।',
  '৳{n} of food cost, but no meals recorded yet. Once somebody eats, it has something to divide by.': 'খাবারে ৳{n} খরচ হয়েছে, কিন্তু এখনো কোনো মিল রেকর্ড হয়নি। কেউ খেলেই ভাগ করার মতো কিছু পাওয়া যাবে।',
  'Meal rate = total approved food expense ÷ total meals': 'মিল রেট = মোট অনুমোদিত খাবারের খরচ ÷ মোট মিল',
