  'Resume meal management. Mess meals, bazar, rate and settlement.': 'মিল ম্যানেজমেন্ট চালিয়ে যান। মেসের মিল, বাজার, রেট আর হিসাব নিষ্পত্তি।',
  'Open meal management. Mess meals, bazar, rate and settlement.': 'মিল ম্যানেজমেন্ট খুলুন। মেসের মিল, বাজার, রেট আর হিসাব নিষ্পত্তি।',
  'RannaBari Mess': 'রান্নাবাড়ি মেস',
  'Resume': 'চালিয়ে যান',
  'A separate app inside this one — mess meals, bazar, expenses, deposits and the monthly rate, kept apart from the shop.': 'এই অ্যাপের ভেতরে আলাদা একটি অ্যাপ — মেসের মিল, বাজার, খরচ, জমা আর মাসিক রেট, দোকান থেকে আলাদা করে রাখা।',
  'Pick up where you left off': 'যেখানে ছেড়েছিলেন সেখান থেকে শুরু করুন',
  'Enter meal management': 'মিল ম্যানেজমেন্টে ঢুকুন',
