  'Your mess’s own books — meals, bazar and money, kept apart from the shop.': 'আপনার মেসের নিজস্ব খাতা — মিল, বাজার আর টাকা, দোকান থেকে আলাদা করে রাখা।',
  'Tap to skip': 'এড়িয়ে যেতে চাপ দিন',
