  'A mess needs an admin — make somebody else admin first.': 'মেসের একজন অ্যাডমিন লাগে — আগে অন্য কাউকে অ্যাডমিন করুন।',
  'Ownership can only pass to another active member.': 'মালিকানা শুধু অন্য একজন সক্রিয় সদস্যকে দেওয়া যায়।',
  'That member has no app account.': 'ওই সদস্যের কোনো অ্যাপ অ্যাকাউন্ট নেই।',
  'That is more than the {n} allowed.': 'এটি অনুমোদিত সীমা {n}-এর বেশি।',
  'This mess does not allow that meal value.': 'এই মেসে ওই মিলের মান অনুমোদিত নয়।',
  'That meal is not set up in this mess.': 'ওই মিল এই মেসে চালু করা নেই।',
  'That expense category could not be found.': 'ওই খরচের খাত পাওয়া যায়নি।',
  'The shares add up to ৳{given}, not ৳{amount}.': 'ভাগগুলোর যোগফল ৳{given}, ৳{amount} নয়।',
  'The shares do not add up to the amount.': 'ভাগগুলোর যোগফল মোট টাকার সাথে মেলে না।',
  'That receipt could not be attached — try a smaller photo.': 'ওই রসিদ যুক্ত করা যায়নি — ছোট কোনো ছবি দিয়ে চেষ্টা করুন।',
  'The cutoff for that meal has passed — send a correction request instead.': 'ওই মিলের কাটঅফ পার হয়ে গেছে — এর বদলে একটি সংশোধনের অনুরোধ পাঠান।',
  'That meal is locked — send a correction request instead.': 'ওই মিল লক হয়ে আছে — এর বদলে একটি সংশোধনের অনুরোধ পাঠান।',
  'That correction request could not be found.': 'ওই সংশোধনের অনুরোধ পাওয়া যায়নি।',
  'That correction has already been decided.': 'ওই সংশোধনের সিদ্ধান্ত আগেই হয়ে গেছে।',
  'A correction for that day is already waiting.': 'ওই দিনের জন্য একটি সংশোধন এরই মধ্যে অপেক্ষায় আছে।',
  'That leave could not be found.': 'ওই ছুটি পাওয়া যায়নি।',
  'That bazar entry could not be found.': 'ওই বাজারের এন্ট্রি পাওয়া যায়নি।',
  'That expense could not be found.': 'ওই খরচ পাওয়া যায়নি।',
  'That deposit could not be found.': 'ওই জমা পাওয়া যায়নি।',
  'That bazar duty could not be found.': 'ওই বাজারের ডিউটি পাওয়া যায়নি।',
  'That cannot be done at this stage.': 'এই পর্যায়ে এটি করা যাবে না।',
  'That has been approved already, so it cannot be edited.': 'এটি আগেই অনুমোদিত হয়েছে, তাই আর বদলানো যাবে না।',
  'Add at least one item before submitting a bazar.': 'বাজার জমা দেওয়ার আগে অন্তত একটি আইটেম যোগ করুন।',
  'That month is settled, so its figures cannot change.': 'ওই মাসের হিসাব চূড়ান্ত, তাই এর সংখ্যাগুলো আর বদলানো যাবে না।',
  'That month is already settled.': 'ওই মাসের হিসাব আগেই চূড়ান্ত হয়ে গেছে।',
  'There is nothing recorded in that month to settle.': 'ওই মাসে নিষ্পত্তি করার মতো কিছু রেকর্ড করা নেই।',
  'Some records are still waiting for approval.': 'কিছু রেকর্ড এখনো অনুমোদনের অপেক্ষায় আছে।',
